-- crm 0004: commercial model (generated by novvus-sdk makemigration, then reviewed).
-- Additive: new tables (lost_reason, tax_rate, product, contact_company, opportunity_line,
-- opportunity_stage_log, quote, quote_line, company_tag) with RLS, and new columns with
-- defaults on company, contact, lead, opportunity and activity. No data is rewritten.
-- down: DROP the nine new tables and the added columns (ALTER TABLE ... DROP COLUMN);
-- no row of the pre-existing tables depends on them.

CREATE TABLE lost_reason (
    name VARCHAR(120) NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (org_id, name)
);

CREATE INDEX ix_lost_reason_org_id ON lost_reason (org_id);

CREATE TABLE tax_rate (
    name VARCHAR(120) NOT NULL, 
    rate NUMERIC(7, 4) NOT NULL, 
    country VARCHAR(2) NOT NULL, 
    is_default BOOLEAN NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (org_id, name)
);

CREATE INDEX ix_tax_rate_org_id ON tax_rate (org_id);

CREATE TABLE company_tag (
    company_id UUID NOT NULL, 
    tag_id UUID NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(tag_id) REFERENCES tag (id) ON DELETE CASCADE, 
    FOREIGN KEY(company_id) REFERENCES company (id) ON DELETE CASCADE, 
    UNIQUE (company_id, tag_id)
);

CREATE INDEX ix_company_tag_org_id ON company_tag (org_id);

CREATE TABLE product (
    sku VARCHAR(60) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(2000) NOT NULL, 
    unit VARCHAR(40) NOT NULL, 
    list_price NUMERIC(14, 2) NOT NULL, 
    currency VARCHAR(3) NOT NULL, 
    tax_rate_id UUID, 
    is_active BOOLEAN NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (org_id, sku), 
    FOREIGN KEY(tax_rate_id) REFERENCES tax_rate (id) ON DELETE SET NULL
);

CREATE INDEX ix_product_org_id ON product (org_id);

CREATE TABLE contact_company (
    contact_id UUID NOT NULL, 
    company_id UUID NOT NULL, 
    role VARCHAR(120) NOT NULL, 
    is_primary BOOLEAN NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(contact_id) REFERENCES contact (id) ON DELETE CASCADE, 
    FOREIGN KEY(company_id) REFERENCES company (id) ON DELETE CASCADE, 
    UNIQUE (contact_id, company_id)
);

CREATE INDEX ix_contact_company_org_id ON contact_company (org_id);

CREATE TABLE opportunity_line (
    opportunity_id UUID NOT NULL, 
    product_id UUID, 
    description VARCHAR(500) NOT NULL, 
    quantity NUMERIC(12, 3) NOT NULL, 
    unit_price NUMERIC(14, 2) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(product_id) REFERENCES product (id) ON DELETE SET NULL, 
    FOREIGN KEY(opportunity_id) REFERENCES opportunity (id) ON DELETE CASCADE
);

CREATE INDEX ix_opportunity_line_org_id ON opportunity_line (org_id);

CREATE TABLE opportunity_stage_log (
    opportunity_id UUID NOT NULL, 
    from_stage_id UUID, 
    to_stage_id UUID, 
    user_id UUID, 
    note VARCHAR(1000) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(to_stage_id) REFERENCES stage (id) ON DELETE SET NULL, 
    FOREIGN KEY(from_stage_id) REFERENCES stage (id) ON DELETE SET NULL, 
    FOREIGN KEY(opportunity_id) REFERENCES opportunity (id) ON DELETE CASCADE
);

CREATE INDEX ix_opportunity_stage_log_org_id ON opportunity_stage_log (org_id);

CREATE TABLE quote (
    number VARCHAR(40) NOT NULL, 
    version INTEGER NOT NULL, 
    previous_id UUID, 
    title VARCHAR(200) NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    company_id UUID, 
    contact_id UUID, 
    opportunity_id UUID, 
    owner_user_id UUID, 
    currency VARCHAR(3) NOT NULL, 
    issued_at DATE, 
    valid_until DATE, 
    discount_percent NUMERIC(5, 2) NOT NULL, 
    subtotal NUMERIC(14, 2) NOT NULL, 
    discount_total NUMERIC(14, 2) NOT NULL, 
    tax_total NUMERIC(14, 2) NOT NULL, 
    total NUMERIC(14, 2) NOT NULL, 
    notes VARCHAR(4000) NOT NULL, 
    terms VARCHAR(4000) NOT NULL, 
    sent_at TIMESTAMP WITHOUT TIME ZONE, 
    decided_at TIMESTAMP WITHOUT TIME ZONE, 
    decision_notes VARCHAR(2000) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(opportunity_id) REFERENCES opportunity (id) ON DELETE SET NULL, 
    FOREIGN KEY(company_id) REFERENCES company (id) ON DELETE SET NULL, 
    UNIQUE (org_id, number, version), 
    FOREIGN KEY(contact_id) REFERENCES contact (id) ON DELETE SET NULL, 
    FOREIGN KEY(previous_id) REFERENCES quote (id) ON DELETE SET NULL
);

CREATE INDEX ix_quote_org_id ON quote (org_id);

CREATE TABLE quote_line (
    quote_id UUID NOT NULL, 
    position INTEGER NOT NULL, 
    product_id UUID, 
    description VARCHAR(500) NOT NULL, 
    quantity NUMERIC(12, 3) NOT NULL, 
    unit_price NUMERIC(14, 2) NOT NULL, 
    discount_percent NUMERIC(5, 2) NOT NULL, 
    tax_rate_id UUID, 
    tax_rate NUMERIC(7, 4) NOT NULL, 
    line_subtotal NUMERIC(14, 2) NOT NULL, 
    line_tax NUMERIC(14, 2) NOT NULL, 
    line_total NUMERIC(14, 2) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(tax_rate_id) REFERENCES tax_rate (id) ON DELETE SET NULL, 
    FOREIGN KEY(product_id) REFERENCES product (id) ON DELETE SET NULL, 
    FOREIGN KEY(quote_id) REFERENCES quote (id) ON DELETE CASCADE
);

CREATE INDEX ix_quote_line_org_id ON quote_line (org_id);

ALTER TABLE activity ADD COLUMN priority VARCHAR(20) NOT NULL DEFAULT 'medium';

ALTER TABLE activity ADD COLUMN outcome VARCHAR(2000) NOT NULL DEFAULT '';

ALTER TABLE activity ADD COLUMN company_id UUID;

ALTER TABLE activity ADD COLUMN contact_id UUID;

